import { produce } from 'immer';
import { Data, Legend, Mark, Scale, Signal } from 'vega';



import { COLOR_SCALE, DEFAULT_COLOR_SCHEME, GROUP_ID, HOVERED_SERIES, LINEAR_COLOR_SCALE, LINE_TYPE_SCALE, OPACITY_SCALE, SERIES_ID, SYMBOL_SHAPE_SCALE, SYMBOL_SIZE_SCALE } from '@spectrum-charts/constants';
import { getColorValue } from '@spectrum-charts/themes';



import { getTableData } from '../data/dataUtils';
import { addFieldToFacetScaleDomain } from '../scale/scaleSpecBuilder';
import { addHighlightSignalLegendHoverEvents, getGenericValueSignal } from '../signal/signalSpecBuilder';
import { getLineWidthPixelsFromLineWidth, getPathFromSymbolShape, getStrokeDashFromLineType } from '../specUtils';
import { ColorFacet, ColorScheme, FacetRef, HighlightedItem, LegendOptions, LegendSpecOptions, LineTypeFacet, LineWidthFacet, ScSpec, SymbolShapeFacet, UserMeta } from '../types';
import { getFacets, getFacetsFromKeys } from './legendFacetUtils';
import { setHoverOpacityForMarks } from './legendHighlightUtils';
import { Facet, getColumnLayoutExpr, getColumns, getDisplayLabelExpr, getEncodings, getHiddenEntriesFilter, getLabelWidthsData, getPagesExpr, getPagesLabelWidthsData, getRowCappedAggregateData, getSymbolType } from './legendUtils';


export const addLegend = produce<
  ScSpec,
  [
    LegendOptions & {
      colorScheme?: ColorScheme;
      index?: number;
      hiddenSeries?: string[];
      highlightedItem?: HighlightedItem;
      highlightedSeries?: string | number;
    }
  ]
>(
  (
    spec,
    {
      align,
      color,
      hasMouseInteraction = false,
      hasOnClick = false,
      hiddenEntries = [],
      hiddenSeries = [],
      highlight = false,
      index = 0,
      isToggleable = false,
      lineType,
      lineWidth,
      position = 'bottom',
      symbolShape,
      colorScheme = DEFAULT_COLOR_SCHEME,
      ...options
    }
  ) => {
    const { formattedColor, formattedLineType, formattedLineWidth, formattedSymbolShape } = formatFacetRefsWithPresets(
      color,
      lineType,
      lineWidth,
      symbolShape,
      colorScheme
    );

    const name = `legend${index}`;

    // put options back together now that all defaults are set
    const legendOptions: LegendSpecOptions = {
      align,
      color: formattedColor,
      hasMouseInteraction,
      hasOnClick,
      hiddenEntries,
      hiddenSeries,
      highlight,
      index,
      isToggleable,
      lineType: formattedLineType,
      lineWidth: formattedLineWidth,
      name,
      position,
      symbolShape: formattedSymbolShape,
      colorScheme,
      ...options,
    };

    if (align !== undefined) {
      if (!spec.usermeta) spec.usermeta = {};
      if (!spec.usermeta.patches) spec.usermeta.patches = [];
      spec.usermeta.patches.push({ legend: { layout: { [position]: { anchor: align } } } });
    }

    // Order matters here. Facets rely on the scales being set up.
    spec.scales = addScales(spec.scales ?? [], legendOptions);

    // get the keys and facet types that are used to divide the data for this visualization
    const { ordinalFacets, continuousFacets } = options.keys
      ? getFacetsFromKeys(options.keys, spec.scales ?? [])
      : getFacets(spec.scales ?? []);

    const legends: Legend[] = [];

    // if there are any categorical facets, add the legend and supporting data, signals and marks
    if (ordinalFacets.length) {
      // When _maxRows is set alongside _preferredColumns on a horizontal legend, render from the
      // row-capped aggregate so the legend itself never exceeds the row cap (see
      // getRowCappedAggregateData) — otherwise it's a pure passthrough of every visible entry.
      const usesRowCap =
        legendOptions._maxRows !== undefined &&
        legendOptions._preferredColumns !== undefined &&
        legendOptions._preferredColumns.length > 0 &&
        ['top', 'bottom'].includes(legendOptions.position);

      // add the legendEntries scale
      // this scale is used to generate every combination of the catergorical facets
      spec.scales.push({
        name: `${name}Entries`,
        type: 'ordinal',
        domain: { data: usesRowCap ? `${name}AggregateCapped` : `${name}Aggregate`, field: `${name}Entries` },
      });

      // just want the unique fields
      const uniqueFacetFields = [...new Set(ordinalFacets.map((facet) => facet.field))];

      spec.data = addData(spec.data ?? [], { ...legendOptions, facets: uniqueFacetFields });
      spec.signals = addSignals(spec.signals ?? [], legendOptions);
      spec.marks = addMarks(spec.marks ?? [], legendOptions);

      // add the legend
      legends.push(getCategoricalLegend(ordinalFacets, legendOptions, spec.usermeta));
    }

    // continuous legends cannot be combined with any other legends
    for (const facet of continuousFacets) {
      // add the legend
      legends.push(getContinuousLegend(facet, legendOptions));
    }

    // if legends is undefined, initialize it as an empty array
    if (spec.legends === undefined) {
      spec.legends = [];
    }
    spec.legends.push(...legends);
  }
);

/**
 * converts facets that could reference preset values to the actual vega supported value
 * Example {value: 'L'} => {value: 3}
 * @param color
 * @param lineType
 * @param lineWidth
 * @param colorScheme
 */
export const formatFacetRefsWithPresets = (
  color: ColorFacet | undefined,
  lineType: LineTypeFacet | undefined,
  lineWidth: LineWidthFacet | undefined,
  symbolShape: SymbolShapeFacet | undefined,
  colorScheme: ColorScheme
) => {
  let formattedColor: FacetRef<string> | undefined;
  if (color && typeof color === 'object') {
    formattedColor = { value: getColorValue(color.value, colorScheme) };
  } else {
    formattedColor = color;
  }

  let formattedLineType: FacetRef<number[]> | undefined;
  if (lineType && typeof lineType === 'object') {
    formattedLineType = { value: getStrokeDashFromLineType(lineType.value) };
  } else {
    formattedLineType = lineType;
  }

  let formattedLineWidth: FacetRef<number> | undefined;
  if (lineWidth && typeof lineWidth === 'object') {
    formattedLineWidth = { value: getLineWidthPixelsFromLineWidth(lineWidth.value) };
  } else {
    formattedLineWidth = lineWidth;
  }

  let formattedSymbolShape: FacetRef<string> | undefined;
  if (symbolShape && typeof symbolShape === 'object') {
    formattedSymbolShape = { value: getPathFromSymbolShape(symbolShape.value) };
  } else {
    formattedSymbolShape = symbolShape;
  }
  return { formattedColor, formattedLineType, formattedLineWidth, formattedSymbolShape };
};

/**
 * gets the legend for all the categorical facets
 * @param facets
 * @param options
 * @returns
 */
const getCategoricalLegend = (facets: Facet[], options: LegendSpecOptions, userMeta: UserMeta): Legend => {
  const { name, position, title, labelLimit, _labelWrap, titleLimit, _preferredColumns } = options;
  // _preferredColumns only applies to horizontal legends, matching getColumns returning undefined for left/right
  const usePreferredColumns =
    _preferredColumns !== undefined && _preferredColumns.length > 0 && ['top', 'bottom'].includes(position);
  // columns/labelLimit/wrapWidth are all resolved together by the ${name}_columnLayout signal (see
  // addSignals)
  const legend: Legend = {
    fill: `${name}Entries`,
    direction: ['top', 'bottom'].includes(position) ? 'horizontal' : 'vertical',
    orient: position,
    title,
    encode: getEncodings(facets, options, userMeta),
    columns: usePreferredColumns ? { signal: `${name}_columnLayout.columns` } : getColumns(position, name, labelLimit),
    labelLimit: usePreferredColumns ? { signal: `${name}_columnLayout.labelLimit` } : labelLimit,
  };
  if (titleLimit !== undefined) legend.titleLimit = titleLimit;
  if (_labelWrap && _labelWrap > 1) {
    // for the legend label offset to work, gridAlign needs to be none to stop the auto-centering
    legend.gridAlign = 'none';
  }
  return legend;
};

/**
 * gets the legend for a continuous facet
 * currently just setup to handle symbolSize since that is the only supported continuous facet
 * @param _facet
 * @param options
 * @returns
 */
export const getContinuousLegend = (facet: Facet, options: LegendSpecOptions): Legend => {
  const { symbolShape } = options;
  // add a switch statement here for the different types of continuous legends
  if (facet.facetType === SYMBOL_SIZE_SCALE) {
    return {
      size: SYMBOL_SIZE_SCALE,
      ...getLegendLayout(options),
      symbolType: getSymbolType(symbolShape),
    };
  }
  return {
    fill: LINEAR_COLOR_SCALE,
    gradientThickness: 10,
    ...getLegendLayout(options),
  };
};

const getLegendLayout = ({ position, title, titleLimit }: LegendSpecOptions): Partial<Legend> => {
  const layout: Partial<Legend> = {
    direction: ['top', 'bottom'].includes(position) ? 'horizontal' : 'vertical',
    orient: position,
    title,
  };
  if (titleLimit !== undefined) layout.titleLimit = titleLimit;
  return layout;
};

/**
 * Adds a new scale that is used to create the legend entries
 */
const addScales = produce<Scale[], [LegendSpecOptions]>((scales, { color, lineType, opacity, symbolShape }) => {
  // it is possible to define fields to facet the data off of on the legend
  // if these fields are not already defined on the scales, we need to add them
  addFieldToFacetScaleDomain(scales, COLOR_SCALE, color);
  addFieldToFacetScaleDomain(scales, LINE_TYPE_SCALE, lineType);
  addFieldToFacetScaleDomain(scales, OPACITY_SCALE, opacity);
  addFieldToFacetScaleDomain(scales, SYMBOL_SHAPE_SCALE, symbolShape);
});

const addMarks = produce<Mark[], [LegendSpecOptions]>((marks, { highlight, keys, name }) => {
  if (highlight) {
    setHoverOpacityForMarks(name, marks, keys);
  }
});

/**
 * Adds a new data set that aggregates the data off of the facet fields
 * This creates a row for every unique combination of the facets in the data
 * Each unique combination gets joined with a pipe to create a single string to use as legend entries
 */
export const addData = produce<Data[], [LegendSpecOptions & { facets: string[] }]>(
  (data, { facets, hiddenEntries, keys, name, position, _preferredColumns, _maxRows }) => {
    // expression for combining all the facets into a single key
    const expr = facets.map((facet) => `datum.${facet}`).join(' + " | " + ');
    data.push(
      {
        name: `${name}Aggregate`,
        source: 'table',
        transform: [
          {
            type: 'aggregate',
            groupby: facets,
          },
          {
            type: 'formula',
            as: `${name}Entries`,
            expr,
          },
          ...getHiddenEntriesFilter(hiddenEntries, name),
        ],
      },
      // Measure the actual max display label width so getColumns can compute an accurate column count.
      {
        name: `${name}_maxLabelWidth`,
        source: `${name}Aggregate`,
        transform: [
          {
            type: 'formula',
            as: 'displayLabel',
            expr: getDisplayLabelExpr(name),
          },
          {
            type: 'formula',
            as: 'labelWidth',
            expr: "getLabelWidth(datum.displayLabel, 'normal', 14)",
          },
          {
            type: 'aggregate',
            fields: ['labelWidth'],
            ops: ['max'],
            as: ['maxLabelWidth'],
          },
        ],
      }
    );

    // When _preferredColumns is set on a horizontal legend, emit the per-entry label-width data that
    // the ${name}_columnLayout signal uses to pick the largest count that fits the currently visible
    // (hiddenEntries-filtered) entries.
    if (_preferredColumns?.length && ['top', 'bottom'].includes(position)) {
      data.push(getLabelWidthsData(name));
    }

    // ${name}_pages needs to plan every entry up front, unaffected by hiddenEntries — otherwise
    // applying one page's hiddenEntries would shrink the  data the next page plan is computed
    // from. ${name}AggregateAll mirrors ${name}Aggregate without the hiddenEntries filter step.
    if (_maxRows !== undefined && _preferredColumns?.length && ['top', 'bottom'].includes(position)) {
      data.push(
        {
          name: `${name}AggregateAll`,
          source: 'table',
          transform: [
            { type: 'aggregate', groupby: facets },
            { type: 'formula', as: `${name}Entries`, expr },
          ],
        },
        getPagesLabelWidthsData(name),
        // Enforces _maxRows at render time so the legend never visibly wraps past its row cap during resize
        getRowCappedAggregateData(name, _maxRows)
      );
    }

    if (keys?.length) {
      const tableData = getTableData(data);
      if (!tableData.transform) {
        tableData.transform = [];
      }
      tableData.transform.push({
        type: 'formula',
        as: `${name}_${GROUP_ID}`,
        expr: keys.map((key) => `datum.${key}`).join(' + " | " + '),
      });
    }

    // add legend hovered series to the trendline and metric range highlighted data
    const highlightedDataSets = data.filter((data) => /.*(Trendline|MetricRange).*highlightedData$/.test(data.name));
    for (const data of highlightedDataSets) {
      if (data.transform?.[0] && 'expr' in data.transform[0]) {
        data.transform[0].expr += ` || datum.${SERIES_ID} === ${name}_${HOVERED_SERIES}`;
      }
    }
  }
);

export const addSignals = produce<Signal[], [LegendSpecOptions]>(
  (signals, { hiddenSeries, highlight, isToggleable, keys, legendLabels, name, position, _preferredColumns, _labelWrap, _maxRows }) => {
    if (highlight) {
      addHighlightSignalLegendHoverEvents(signals, name, Boolean(isToggleable || hiddenSeries), keys);
    }

    // Always emit _labels so the _maxLabelWidth data transform can safely reference it.
    // Defaults to [] when no legendLabels prop is set; the lookup falls through to datum.${name}Entries.
    signals.push(getGenericValueSignal(`${name}_labels`, legendLabels ?? []));

    // _preferredColumns only applies to horizontal legends, matching getColumns returning undefined for left/right
    const usePreferredColumns =
      _preferredColumns !== undefined && _preferredColumns.length > 0 && ['top', 'bottom'].includes(position);
    if (usePreferredColumns) {
      // ${name}_pages is only useful for external pagination once _maxRows is set; it's not needed
      // to render the legend itself, so it's skipped otherwise.
      if (_maxRows !== undefined) {
        signals.push({ name: `${name}_pages`, update: getPagesExpr(name, _preferredColumns, _maxRows, _labelWrap) });
      }
      // compute ${name}_columnLayout AFTER the page layout is computed, to get the correct per page column count decided by ${name}_pages
      signals.push({
        name: `${name}_columnLayout`,
        update: getColumnLayoutExpr(name, _preferredColumns, _labelWrap, _maxRows),
      });
    }
  }
);
