import { LineMark, Mark, NumericValueRef, ProductionRule, RuleMark, SymbolMark } from 'vega';

import {
  CONTROLLED_HIGHLIGHTED_SERIES,
  CONTROLLED_HIGHLIGHTED_TABLE,
  DEFAULT_INTERACTION_MODE,
  DEFAULT_OPACITY_RULE,
  DIMENSION_HOVER_AREA,
  FADE_FACTOR,
  HOVER_RULE,
  HOVERED_ITEM,
  INTERACTION_MODE,
  LAST_RSC_SERIES_ID,
  SELECTED_SERIES,
  SERIES_ID,
} from '@spectrum-charts/constants';

import { getPopovers } from '../chartPopover/chartPopoverUtils';
import {
  getColorProductionRule,
  getItemHoverArea,
  getLineWidthProductionRule,
  getMetricRangeHoverVisibilityOpacityRules,
  getOpacityProductionRule,
  getStrokeDashProductionRule,
  getVoronoiPath,
  getXProductionRule,
  hasPopover,
  getTooltip,
} from '../marks/markUtils';
import { getDualAxisScaleNames } from '../scale/scaleUtils';
import { ScaleType } from '../types';
import { getDimensionField } from './lineDataUtils';
import {
  getHighlightBackgroundPoint,
  getHighlightPoint,
  getSecondaryHighlightPoint,
  getSelectRingPoint,
  getSelectionPoint,
} from './linePointUtils';
import { isDualMetricAxis, LineMarkOptions } from './lineUtils';

/**
 * Gets the Y encoding for line marks with dual metric axis support
 * @param lineMarkOptions - Line mark options including metricAxis and dualMetricAxis
 * @param metric - The metric field name
 * @returns Y encoding with conditional scale selection for dual metric axis
 */
export const getLineYEncoding = (lineMarkOptions: LineMarkOptions, metric: string): ProductionRule<NumericValueRef> => {
  const { metricAxis } = lineMarkOptions;
  
  if (isDualMetricAxis(lineMarkOptions)) {
    const baseScaleName = metricAxis || 'yLinear';
    const scaleNames = getDualAxisScaleNames(baseScaleName);
    
    return [
      {
        test: `datum.${SERIES_ID} === ${LAST_RSC_SERIES_ID}`,
        scale: scaleNames.secondaryScale,
        field: metric,
      },
      {
        scale: scaleNames.primaryScale,
        field: metric,
      },
    ];
  }
  
  return [{ scale: metricAxis || 'yLinear', field: metric }];
};

const getClampedScaleSignal = (yScale: string, metric: string): string =>
  `clamp(scale('${yScale}', datum['${metric}']), 0, height)`;

/**
 * Gets a Y encoding clamped to [0, height], for hover marks whose metric may fall outside the y domain.
 * @param lineMarkOptions - Line mark options including metricAxis and dualMetricAxis
 * @param metric - The metric field name
 * @returns Clamped Y encoding with conditional scale selection for dual metric axis
 */
export const getClampedYEncoding = (lineMarkOptions: LineMarkOptions, metric: string): ProductionRule<NumericValueRef> => {
  const { metricAxis } = lineMarkOptions;

  if (isDualMetricAxis(lineMarkOptions)) {
    const baseScaleName = metricAxis || 'yLinear';
    const scaleNames = getDualAxisScaleNames(baseScaleName);

    return [
      {
        test: `datum.${SERIES_ID} === ${LAST_RSC_SERIES_ID}`,
        signal: getClampedScaleSignal(scaleNames.secondaryScale, metric),
      },
      { signal: getClampedScaleSignal(scaleNames.primaryScale, metric) },
    ];
  }

  return [{ signal: getClampedScaleSignal(metricAxis || 'yLinear', metric) }];
};

/**
 * generates a line mark
 * @param lineOptions
 * @param dataSource
 * @returns LineMark
 */
export const getLineMark = (lineMarkOptions: LineMarkOptions, dataSource: string): LineMark => {
  const {
    chartPopovers,
    color,
    colorScheme,
    dimension,
    lineType,
    lineWidth,
    metric,
    name,
    opacity,
    s2,
    scaleType,
  } = lineMarkOptions;
  const popovers = getPopovers(chartPopovers ?? [], name);
  const popoverWithDimensionHighlightExists = popovers.some(
    ({ UNSAFE_highlightBy }) => UNSAFE_highlightBy === 'dimension'
  );

  return {
    name,
    description: name,
    type: 'line',
    from: { data: dataSource },
    interactive: false,
    encode: {
      enter: {
        y: getLineYEncoding(lineMarkOptions, metric),
        stroke: getColorProductionRule(color, colorScheme, undefined, s2),
        strokeDash: getStrokeDashProductionRule(lineType),
        strokeOpacity: getOpacityProductionRule(opacity),
        strokeWidth: getLineWidthProductionRule(lineWidth),
        defined: { signal: `isValid(datum["${metric}"])` },
      },
      update: {
        // this has to be in update because when you resize the window that doesn't rebuild the spec
        // but it may change the x position if it causes the chart to resize
        x: getXProductionRule(scaleType, dimension),
        ...(popoverWithDimensionHighlightExists ? {} : { opacity: getLineOpacity(lineMarkOptions) }),
      },
    },
  };
};

export const getLineOpacity = ({
  displayOnHover,
  comboSiblingNames,
  hoverContext,
  displayOnHoverTrigger,
  interactiveMarkName,
  interactionMode,
  isMetricRange,
  popoverMarkName,
  isHighlightedByGroup,
  highlightedItem,
}: LineMarkOptions): ProductionRule<NumericValueRef> => {
  if (!interactiveMarkName && highlightedItem === undefined) return [DEFAULT_OPACITY_RULE];

  if (
    isMetricRange &&
    (displayOnHover === 'metric' || displayOnHover === true) &&
    hoverContext &&
    highlightedItem === undefined
  ) {
    return getMetricRangeHoverVisibilityOpacityRules(hoverContext, 'show', displayOnHoverTrigger);
  }

  if ((!interactiveMarkName || displayOnHover === true) && highlightedItem === undefined) {
    return [DEFAULT_OPACITY_RULE];
  }

  const strokeOpacityRules: ProductionRule<NumericValueRef> = [];

  if (interactiveMarkName) {
    if (interactionMode === INTERACTION_MODE.DIMENSION) {
      const dimensionHoverSignal = `${interactiveMarkName}_${DIMENSION_HOVER_AREA}_${HOVERED_ITEM}`;
      strokeOpacityRules.push(
        {
          test: `isValid(${dimensionHoverSignal})`,
          value: 1,
        },
        {
          test: `isValid(${interactiveMarkName}_${HOVERED_ITEM})`,
          signal: `${interactiveMarkName}_${HOVERED_ITEM}.${SERIES_ID} === datum.${SERIES_ID} ? 1 : ${FADE_FACTOR}`,
        }
      );
    } else if (isHighlightedByGroup) {
      strokeOpacityRules.push({
        test: `length(data('${interactiveMarkName}_highlightedData'))`,
        signal: `indexof(pluck(data('${interactiveMarkName}_highlightedData'), '${SERIES_ID}'), datum.${SERIES_ID}) !== -1 ? 1 : ${FADE_FACTOR}`,
      });
    } else {
      const isHoveredSeries = `${interactiveMarkName}_${HOVERED_ITEM}.${SERIES_ID} === datum.${SERIES_ID}`;
      const isControlledTableSeries = `indexof(pluck(data('${CONTROLLED_HIGHLIGHTED_TABLE}'), '${SERIES_ID}'), datum.${SERIES_ID}) > -1`;
      const isControlledSeries = `isValid(${CONTROLLED_HIGHLIGHTED_SERIES}) && ${CONTROLLED_HIGHLIGHTED_SERIES} === datum.${SERIES_ID}`;
      strokeOpacityRules.push({
        test: `isValid(${interactiveMarkName}_${HOVERED_ITEM})`,
        signal: `${isHoveredSeries} || ${isControlledTableSeries} || ${isControlledSeries} ? 1 : ${FADE_FACTOR}`,
      });
    }
  }

  strokeOpacityRules.push(
    {
      test: `length(data('${CONTROLLED_HIGHLIGHTED_TABLE}'))`,
      signal: `indexof(pluck(data('${CONTROLLED_HIGHLIGHTED_TABLE}'), '${SERIES_ID}'), datum.${SERIES_ID}) > -1 ? 1 : ${FADE_FACTOR}`,
    },
    {
      test: `isValid(${CONTROLLED_HIGHLIGHTED_SERIES})`,
      signal: `${CONTROLLED_HIGHLIGHTED_SERIES} === datum.${SERIES_ID} ? 1 : ${FADE_FACTOR}`,
    }
  );

  if (popoverMarkName) {
    strokeOpacityRules.push({
      test: `isValid(${SELECTED_SERIES})`,
      signal: `${SELECTED_SERIES} === datum.${SERIES_ID} ? 1 : ${FADE_FACTOR}`,
    });
  }

  if (comboSiblingNames?.length) {
    const test = comboSiblingNames.map((siblingName) => `isValid(${siblingName}_${HOVERED_ITEM})`).join(' || ');
    strokeOpacityRules.push({
      test,
      value: FADE_FACTOR,
    });
  }

  strokeOpacityRules.push(DEFAULT_OPACITY_RULE);

  return strokeOpacityRules;
};

/**
 * All the marks that get displayed when hovering or selecting a point on a line
 * @param lineMarkOptions
 * @param dataSource
 * @param secondaryHighlightedMetric
 * @returns
 */
export const getLineHoverMarks = (
  lineOptions: LineMarkOptions,
  dataSource: string,
  secondaryHighlightedMetric?: string
): Mark[] => {
  const { dimension, name, scaleType } = lineOptions;
  return [
    // vertical rule shown for the hovered or selected point
    getHoverRule(dimension, name, scaleType),
    // point behind the hovered or selected point used to prevent bacgorund elements from being visible through low opacity point
    getHighlightBackgroundPoint(lineOptions),
    // if has popover, add selection ring and selection point
    ...(hasPopover(lineOptions) ? [getSelectRingPoint(lineOptions), getSelectionPoint(lineOptions)] : []),
    // hover or select point
    getHighlightPoint(lineOptions),
    // additional point that gets highlighted like the trendline or raw line point
    ...(secondaryHighlightedMetric ? [getSecondaryHighlightPoint(lineOptions, secondaryHighlightedMetric)] : []),
    // get interactive marks for the line
    ...getInteractiveMarks(dataSource, lineOptions),
  ];
};

const getHoverRule = (dimension: string, name: string, scaleType: ScaleType): RuleMark => {
  return {
    name: `${name}${HOVER_RULE}`,
    description: `${name}${HOVER_RULE}`,
    type: 'rule',
    from: { data: `${name}_highlightedData` },
    interactive: false,
    encode: {
      enter: {
        y: { value: 0 },
        y2: { signal: 'height' },
        strokeWidth: { value: 1 },
      },
      update: {
        x: getXProductionRule(scaleType, dimension),
        opacity: { signal: `length(data('${name}_selectedData')) > 0 ? 0 : 1` },
      },
    },
  };
};

const getInteractiveMarks = (dataSource: string, lineOptions: LineMarkOptions): Mark[] => {
  const { interactionMode = DEFAULT_INTERACTION_MODE } = lineOptions;

  const tooltipMarks = {
    nearest: getVoronoiMarks,
    item: getItemHoverMarks,
    dimension: getDimensionInteractionMarks,
  };

  return tooltipMarks[interactionMode](lineOptions, dataSource);
};

const getVoronoiMarks = (lineOptions: LineMarkOptions, dataSource: string): Mark[] => {
  const { name } = lineOptions;

  return [
    // points used for the voronoi transform
    getLinePointsForVoronoi(lineOptions, dataSource),
    // voronoi transform used to get nearest point paths
    getVoronoiPath(lineOptions, `${name}_pointsForVoronoi`),
  ];
};

/**
 * Gets the Y encoding for voronoi points, extending the standard line Y encoding with
 * conditional fallbacks for MetricRange hover point metrics. This allows voronoi cells
 * to be generated for rows where the line metric is null but a MetricRange metric is valid
 * (e.g. forecast rows).
 * @param lineOptions - Line options
 * @param metric - The line metric field name
 * @returns Y encoding for voronoi points
 */
export const getVoronoiYEncoding = (lineOptions: LineMarkOptions, metric: string): ProductionRule<NumericValueRef> => {
  const { metricAxis, metricRanges = [] } = lineOptions;

  if (isDualMetricAxis(lineOptions)) {
    return getLineYEncoding(lineOptions, metric);
  }

  const hoverPointMetrics = metricRanges
    .filter(mr => mr.hoverPoint && mr.metric)
    .map(mr => mr.metric as string);

  if (hoverPointMetrics.length === 0) {
    return getLineYEncoding(lineOptions, metric);
  }

  const yScale = metricAxis || 'yLinear';
  return [
    { test: `isValid(datum["${metric}"])`, scale: yScale, field: metric },
    // Clamp metric range y positions to [0, height] so out-of-domain values don't produce
    // negative y-coordinates. An unclamped out-of-domain point creates an abnormally large
    // voronoi cell that dominates the visible chart area and causes hover flicker.
    ...hoverPointMetrics.map(mrMetric => ({
      test: `isValid(datum["${mrMetric}"])`,
      signal: getClampedScaleSignal(yScale, mrMetric),
    })),
    { scale: yScale, field: metric },
  ];
};

/**
 * Gets the points used for the voronoi calculation for line charts with dual metric axis support
 * @param lineOptions - Line options including dual metric axis settings
 * @param dataSource - the name of the data source that will be used in the voronoi calculation
 * @returns SymbolMark
 */
const getLinePointsForVoronoi = (lineOptions: LineMarkOptions, dataSource: string): Mark => {
  const { dimension, metric, name, scaleType } = lineOptions;

  return {
    name: `${name}_pointsForVoronoi`,
    description: `${name}_pointsForVoronoi`,
    type: 'symbol',
    from: { data: dataSource },
    interactive: false,
    encode: {
      enter: {
        y: getVoronoiYEncoding(lineOptions, metric),
        fill: { value: 'transparent' },
        stroke: { value: 'transparent' },
      },
      update: {
        x: getXProductionRule(scaleType, dimension),
      },
    },
  };
};

const getItemHoverMarks = (lineOptions: LineMarkOptions, dataSource: string): Mark[] => {
  const { chartTooltips = [], dimension, metric, name, scaleType } = lineOptions;

  return [
    // area around item that triggers hover
    getItemHoverArea(chartTooltips, dataSource, dimension, metric, name, scaleType, getVoronoiYEncoding(lineOptions, metric)),
  ];
};

const getDimensionInteractionMarks = (lineOptions: LineMarkOptions, dataSource: string): Mark[] => {
  const { chartTooltips = [], dimension, metric, name, scaleType } = lineOptions;
  const dimensionField = getDimensionField(scaleType, dimension);

  return [
    // invisible points at fixed y for dimension-level voronoi
    getXAxisVoronoiPoints(name, dimensionField, scaleType),
    getXAxisVoronoiPath(lineOptions, `${name}_xAxisVoronoiPoints`, dimensionField),
    getItemHoverArea(chartTooltips, dataSource, dimension, metric, name, scaleType, getVoronoiYEncoding(lineOptions, metric)),
  ];
};

/**
 * Creates invisible symbol marks at a fixed y position for each unique dimension value.
 * These are used as input for the x-axis voronoi transform to create vertical hover strips.
 */
const getXAxisVoronoiPoints = (name: string, dimensionField: string, scaleType: ScaleType): SymbolMark => {
  return {
    name: `${name}_xAxisVoronoiPoints`,
    description: `Hidden points at fixed y for x-axis voronoi`,
    type: 'symbol',
    from: { data: `${name}_uniqueXValues` },
    interactive: false,
    encode: {
      enter: {
        y: { signal: '0' },
        fill: { value: 'transparent' },
        stroke: { value: 'transparent' },
      },
      update: {
        x: getXProductionRule(scaleType, dimensionField),
      },
    },
  };
};

/**
 * Creates a voronoi path mark from the x-axis voronoi points.
 * The resulting paths are vertical strips that cover the chart area, one per dimension value.
 * Used for dimension-level hover detection.
 */
const getXAxisVoronoiPath = (lineOptions: LineMarkOptions, dataSource: string, dimensionField: string): Mark => {
  const { chartTooltips, name: markName } = lineOptions;
  const dimensionHoverAreaName = `${markName}_${DIMENSION_HOVER_AREA}`;

  return {
    name: `${markName}_xAxisVoronoi`,
    description: `Voronoi on hidden flat line for x-axis tracking`,
    type: 'path',
    from: { data: dataSource },
    encode: {
      enter: {
        fill: { value: 'transparent' },
        stroke: { value: 'transparent' },
        isVoronoi: { value: true },
        tooltip: getTooltip(chartTooltips ?? [], dimensionHoverAreaName, true, { dimension: dimensionField }),
      },
      update: {},
    },
    transform: [
      {
        type: 'voronoi',
        x: 'datum.x',
        y: 'datum.y',
        size: [{ signal: 'max(width, 1)' }, { signal: 'max(height, 1)' }],
      },
    ],
  };
};

